package fr.cake.client;
import net.minecraft.client.Minecraft;import com.mojang.blaze3d.pipeline.*;import com.mojang.blaze3d.buffers.GpuBuffer;import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.shaders.UniformType;import net.minecraft.resources.Identifier;import java.nio.*;import java.io.*;import java.util.*;
public final class SpotifyVisualizer {
 private static volatile Process process;private static volatile float peak;private static volatile String status="Module désactivé";private static float smooth;private static long retry,last;private static GpuBuffer uniform;
 private static final ByteBuffer DATA=ByteBuffer.allocateDirect(32).order(ByteOrder.nativeOrder());
 private static final RenderPipeline PIPE=RenderPipeline.builder(net.minecraft.client.renderer.RenderPipelines.POST_PROCESSING_SNIPPET).withLocation(Identifier.fromNamespaceAndPath("cakeclient","pipeline/music_viz")).withVertexShader(Identifier.withDefaultNamespace("core/screenquad")).withFragmentShader(Identifier.fromNamespaceAndPath("cakeclient","core/music_viz")).withUniform("MusicData",UniformType.UNIFORM_BUFFER).withBlend(BlendFunction.TRANSLUCENT).build();
 public static String status(){return LyricsService.media()==null?LyricsService.status():"Spotify · "+LyricsService.media().title();}
 public static void tick(){var s=CakeClient.settings;if(!s.visualizer){if(process!=null)close();return;}if(!System.getProperty("os.name","").toLowerCase(Locale.ROOT).contains("win")){status="Détection audio : Windows 10 / 11 requis";return;}if(process!=null||System.nanoTime()<retry)return;retry=System.nanoTime()+15_000_000_000L;Thread worker=new Thread(()->{try(var in=SpotifyVisualizer.class.getResourceAsStream("/assets/cakeclient/bridge/audio-meter.ps1")){String source=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8),encoded=Base64.getEncoder().encodeToString(source.getBytes(java.nio.charset.StandardCharsets.UTF_16LE));var child=new ProcessBuilder("powershell.exe","-NoLogo","-NoProfile","-NonInteractive","-WindowStyle","Hidden","-EncodedCommand",encoded).redirectError(ProcessBuilder.Redirect.DISCARD).start();process=child;try(var reader=new BufferedReader(new InputStreamReader(child.getInputStream()))){String line;while((line=reader.readLine())!=null){try{peak=Math.clamp(Float.parseFloat(line.trim()),0,1);status="Niveau audio Windows actif · Spotify détecté si en lecture";}catch(NumberFormatException ignored){}}}child.destroy();}catch(Exception e){status="Sortie audio indisponible";}finally{process=null;peak=0;}},"Cake-Audio-Meter");worker.setDaemon(true);worker.start();}
 public static float level(){float target=LyricsService.media()!=null&&LyricsService.media().playing()?(float)Math.sqrt(peak):0;long now=System.nanoTime();float dt=last==0?.016f:Math.min(.1f,(now-last)/1e9f);last=now;smooth+=(target-smooth)*(1-(float)Math.exp(-dt*12));return smooth;}
 public static void render(){}
 public static void close(){var p=process;if(p!=null)p.destroy();process=null;peak=0;if(uniform!=null){uniform.close();uniform=null;}}
}
